"""Core text operations."""
import re


def word_count(text: str) -> int:
    """Number of whitespace-separated words. Punctuation-only tokens (with no letter or digit) are not counted."""
    def is_word(token: str) -> bool:
        return bool(re.search(r'\w', token))
    return len([t for t in text.split() if is_word(t)])

